using System;using System.IO;using System.Linq;using IGM;
class Verify019{static void Main(string[]args){string folder=Path.Combine(Path.GetTempPath(),"igm51 core "+Guid.NewGuid().ToString("N"),"IGM_datos");Directory.CreateDirectory(folder);string bundle=Path.GetDirectoryName(folder),legacy=Path.Combine(Directory.GetParent(bundle).FullName,"IGM_v031_datos");Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"exploracion_v045.tsv"),"#legacy\n");if(Data.MigrateBundle(bundle)!=folder||File.ReadAllText(Path.Combine(folder,"exploracion.tsv"))!="#legacy\n")throw new Exception("Migration path");File.WriteAllText(Path.Combine(folder,"exploracion.tsv"),"#current\n");Data.MigrateBundle(bundle);if(File.ReadAllText(Path.Combine(folder,"exploracion.tsv"))!="#current\n")throw new Exception("Migration overwrite");Project p=new Project();foreach(string save in args){Project x=Data.Import(save,"");p.Merge(x);}Console.WriteLine("Imported "+p.Systems.Count+" systems / "+p.Alliances.Count+" alliances");foreach(var a in p.Alliances)a.ColorRGB=0;string management=Path.Combine(folder,"gestion_sistemas.tsv");File.WriteAllText(management,"#preserve favourite exclusions\n");Console.WriteLine(Data.Export(p,folder,false));string f=Path.Combine(folder,"catalogo_observado.jsonl");string first=File.ReadAllText(f);Console.WriteLine(Data.Export(p,folder,false));if(first!=File.ReadAllText(f)||File.ReadAllText(management)!="#preserve favourite exclusions\n")throw new Exception("Export overwrite/idempotence");Project loaded=Data.LoadMod(folder);if(loaded.Systems.Count==0)throw new Exception("No exported systems");Console.WriteLine("PASS actual saves, new target, append, reimport, repeated-export idempotence, management preserved");}}
